package com.pointverse.app;
import android.test.InstrumentationTestCase;import java.util.*;
@SuppressWarnings("deprecation")
public final class UniverseSceneTest extends InstrumentationTestCase {
 static PointStore.Point point(String id,String domain,String topic){PointStore.Point p=new PointStore.Point();p.id=id;p.title="想法 "+id;p.body="内容 "+id;p.domain=domain;p.topic=topic;p.manual="";p.project="";p.expression="";p.embedding="";p.analysis="";p.locale="zh-CN";return p;}
 UniverseScene scene(int count)throws Exception {List<PointStore.Point> points=new ArrayList<>();for(int i=0;i<count;i++)points.add(point("point"+i,"领域"+(i%4),"主题"+(i%3)));return new UniverseScene(points,new SemanticIndex(getInstrumentation().getTargetContext()),new UniverseScene.State());}
 public void testIosClickFitAndMonotonicPlanetSize(){assertEquals(316.8,UniverseScene.clickedDiameter(360,700),.001);assertEquals(0.48,UniverseScene.planetRadius(0),1e-8);assertTrue(UniverseScene.planetRadius(100)>UniverseScene.planetRadius(10));assertTrue(UniverseScene.planetRadius(100000)<1.181);}
 public void testIosEasedRelativeCameraFlight(){assertEquals(4,UniverseScene.flight(1,16,.5),1e-8);assertEquals(1,UniverseScene.flight(1,16,0),1e-8);assertEquals(16,UniverseScene.flight(1,16,1),1e-8);assertEquals(-1,UniverseScene.flight(-1,1,.5),0);}
 public void testIdlePauseAndBackgroundDoNotJump(){assertEquals(0,UniverseScene.orbitDelta(1,2,6),0);assertEquals(.1,UniverseScene.orbitDelta(1,100,6),1e-8);assertEquals(.05,UniverseScene.orbitDelta(6,6.05,6),1e-8);}
 public void testSearchTurnsAnyPointToVisibleFront(){for(String id:Arrays.asList("a","b","c","d")){UniverseScene.V v=UniverseScene.seedUnit(id),front=UniverseScene.Rotation.face(v).apply(v);assertEquals(0,front.x,1e-8);assertEquals(0,front.y,1e-8);assertEquals(1,front.z,1e-8);}}
 public void testSurfaceDraggingUsesProjectedRadius(){UniverseScene.Rotation a=UniverseScene.Rotation.y(40.0/100),b=UniverseScene.Rotation.y(40.0/400);assertTrue(a.apply(new UniverseScene.V(0,0,1)).x>b.apply(new UniverseScene.V(0,0,1)).x);}
 public void testPinchKeepsPlanetScreenAnchorAndHasNoLodJump()throws Exception {UniverseScene s=scene(20);UniverseScene.Planet p=s.planets.get(0);double[] fit=s.destination(p,160,360,600);s.state.cameraX=fit[0]-.5;s.state.cameraY=fit[1]+.3;s.state.distance=fit[2];UniverseScene.Projection before=s.project(p,360,600);s.magnify(1.2,p,360,600);UniverseScene.Projection after=s.project(p,360,600);assertEquals(before.x,after.x,1e-7);assertEquals(before.y,after.y,1e-7);assertEquals(before.r*1.2,after.r,1e-7);s.magnify(1/1.2,p,360,600);assertEquals(before.r,s.project(p,360,600).r,1e-7);}
 public void testPanChangesCameraWithoutRotatingSurface()throws Exception {UniverseScene s=scene(10);UniverseScene.Planet p=s.planets.get(0);double[] matrix=s.rotation(p).m.clone();s.pan(50,20,360,600);assertTrue(s.state.cameraX<0);assertTrue(s.state.cameraY>0);assertTrue(Arrays.equals(matrix,s.rotation(p).m));}
 public void testClustersRemainStableDuringRotation()throws Exception {UniverseScene s=scene(50);UniverseScene.Planet p=s.planets.get(0);String a=members(s.clusters(p,100));s.rotate(p,100,100,100);assertEquals(a,members(s.clusters(p,100)));assertTrue(s.clusters(p,1000).size()>=s.clusters(p,100).size());}
 String members(List<UniverseScene.Cluster> groups){StringBuilder b=new StringBuilder();for(UniverseScene.Cluster c:groups){for(UniverseScene.Node n:c.members)b.append(n.point.id).append(',');b.append(';');}return b.toString();}
 public void testOverviewContainsEveryPlanet()throws Exception {UniverseScene s=scene(40);double[] camera=s.overview(360,600);s.state.cameraX=camera[0];s.state.cameraY=camera[1];s.state.distance=camera[2];for(UniverseScene.Planet p:s.planets){UniverseScene.Projection v=s.project(p,360,600);assertNotNull(v);assertTrue(v.x-v.r>=0&&v.x+v.r<=360);assertTrue(v.y-v.r>=0&&v.y+v.r<=600);}}
 public void testFollowingOrbitKeepsSelectedPlanetStationary()throws Exception {UniverseScene s=scene(20);UniverseScene.Planet p=s.planets.get(0);s.state.target=p.id;UniverseScene.Projection a=s.project(p,360,600);s.advance(.1);UniverseScene.Projection b=s.project(p,360,600);assertEquals(a.x,b.x,1e-8);assertEquals(a.y,b.y,1e-8);assertEquals(a.r,b.r,1e-8);}
 public void testStateRetainsNegativeCameraOrientationAndTreeExpansion(){UniverseScene.State s=new UniverseScene.State();s.distance=-.5;s.cameraX=12;s.cameraY=-3;s.target="planet";s.focused="point";s.expanded.add("topic");s.rotations.put("planet",UniverseScene.Rotation.x(.8));UniverseScene.State copy=UniverseScene.State.parse(s.json());assertEquals(-.5,copy.distance,0);assertEquals(s.cameraX,copy.cameraX,0);assertEquals("point",copy.focused);assertTrue(copy.expanded.contains("topic"));assertEquals(s.rotations.get("planet").m[4],copy.rotations.get("planet").m[4],1e-8);}
 public void testStarHasVisibleMinimumAndGrowsWithDistanceAndCollection(){assertEquals(8,UniverseScene.starRadius(0,.1),0);assertTrue(UniverseScene.starRadius(100,20)>UniverseScene.starRadius(1,20));assertTrue(UniverseScene.starRadius(100,20)>UniverseScene.starRadius(100,10));assertEquals(40,UniverseScene.starRadius(1000,10000),0);}

}
